import{_ as e,o as r,c as s,a2 as d}from"./chunks/framework.C8nVztS1.js";const p=JSON.parse('{"title":"Community pain points","description":"Upstream issues that motivated untestutils, how we address them, and where we reply.","frontmatter":{"title":"Community pain points","description":"Upstream issues that motivated untestutils, how we address them, and where we reply.","outline":"deep"},"headers":[],"relativePath":"community-pain-points.md","filePath":"community-pain-points.md","lastUpdated":1790411047000}'),a={name:"community-pain-points.md"};function o(i,t,n,u,l,h){return r(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="community-pain-points" tabindex="-1">Community pain points <a class="header-anchor" href="#community-pain-points" aria-label="Permalink to &quot;Community pain points&quot;">​</a></h1><p>Tracked while designing untestutils. Status: <code>addressed</code> (first-class in the harness), <code>documented</code> (clear docs / escape hatches), <code>out-of-scope</code> (unit-env / framework bugs we do not claim to replace).</p><p>Proof dogfood (external consumer): <a href="https://github.com/s00d/nuxt-i18n-micro/actions/runs/35586385667/job/106290602444" target="_blank" rel="noreferrer">nuxt-i18n-micro CI</a> — <strong>265 e2e</strong> tests in <strong>~4 minutes</strong> (<code>test:e2e</code> step), shared prepare via untestutils.</p><h2 id="nuxt-test-utils-—-e2e-speed-reuse" tabindex="-1">@nuxt/test-utils — e2e speed / reuse <a class="header-anchor" href="#nuxt-test-utils-—-e2e-speed-reuse" aria-label="Permalink to &quot;@nuxt/test-utils — e2e speed / reuse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pain</th><th>Issue</th><th>Status</th><th>How untestutils handles it</th></tr></thead><tbody><tr><td>Slow <code>setup</code> on every rerun</td><td><a href="https://github.com/nuxt/test-utils/issues/314" target="_blank" rel="noreferrer">#314</a></td><td>addressed</td><td>Shared prepare + content-hash cache + <code>prewarm</code></td></tr><tr><td>Opt-in Nuxt app reuse across workers</td><td><a href="https://github.com/nuxt/test-utils/issues/1750" target="_blank" rel="noreferrer">#1750</a></td><td>addressed (e2e)</td><td>Target registry + lock-by-identity; one prepare, many workers — <strong>e2e only</strong>; unit reuse is separate (see below)</td></tr><tr><td>Shared server faster in CI</td><td><a href="https://github.com/nuxt/test-utils/issues/925" target="_blank" rel="noreferrer">#925</a></td><td>addressed</td><td>First-class shared serve / recipe identity</td></tr><tr><td>Vitest workspaces</td><td><a href="https://github.com/nuxt/test-utils/issues/664" target="_blank" rel="noreferrer">#664</a></td><td>documented</td><td>Absolute recipe roots; e2e vs unit as separate Vitest projects</td></tr><tr><td>Playwright fixture timeout</td><td><a href="https://github.com/nuxt/test-utils/issues/861" target="_blank" rel="noreferrer">#861</a></td><td>documented</td><td>Readiness HTTP + sane hook timeouts</td></tr><tr><td>Firefox hydration <code>waitUntil</code></td><td><a href="https://github.com/nuxt/test-utils/issues/1671" target="_blank" rel="noreferrer">#1671</a></td><td>out-of-scope</td><td>Browser-specific; Chromium dogfood first</td></tr><tr><td>Cookies in context</td><td><a href="https://github.com/nuxt/test-utils/issues/325" target="_blank" rel="noreferrer">#325</a></td><td>documented</td><td>Live target + Playwright context; utils for cookie asserts</td></tr><tr><td>Nitro Azure preset e2e</td><td><a href="https://github.com/nuxt/test-utils/issues/908" target="_blank" rel="noreferrer">#908</a></td><td>out-of-scope</td><td>v1: <code>node</code> / <code>static</code> / Nuxt server modes</td></tr><tr><td><code>setup()</code> clobbers <code>console.log</code></td><td><a href="https://github.com/nuxt/test-utils/issues/350" target="_blank" rel="noreferrer">#350</a></td><td>addressed</td><td>Child stdout passthrough by default; opt-in capture</td></tr><tr><td><code>multiApp</code> breaks test-utils</td><td><a href="https://github.com/nuxt/test-utils/issues/1521" target="_blank" rel="noreferrer">#1521</a></td><td>addressed</td><td>Explicit recipe <code>root</code> / id per app</td></tr></tbody></table><h2 id="nuxt-test-utils-—-unit-nuxt-environment" tabindex="-1">@nuxt/test-utils — unit / Nuxt environment <a class="header-anchor" href="#nuxt-test-utils-—-unit-nuxt-environment" aria-label="Permalink to &quot;@nuxt/test-utils — unit / Nuxt environment&quot;">​</a></h2><p>Mostly <strong>out-of-scope</strong> for the recipe e2e core. Optional <code>@untestutils/nuxt</code> + <code>vitest-environment-untestutils</code> cover a separate unit surface — not a drop-in for every mock/<code>mountSuspended</code> request.</p><table tabindex="0"><thead><tr><th>Pain</th><th>Issue</th><th>Status</th></tr></thead><tbody><tr><td>Opt-in worker-scoped Nuxt app reuse (unit)</td><td><a href="https://github.com/nuxt/test-utils/issues/1750" target="_blank" rel="noreferrer">#1750</a>, <a href="https://github.com/s00d/untestutils/issues/1" target="_blank" rel="noreferrer">untestutils#1</a>, <a href="https://github.com/nuxt/test-utils/pull/1821" target="_blank" rel="noreferrer">#1821</a></td><td>addressed (<code>appIsolation: &#39;worker&#39;</code> + soft reset + browser-entry; keep opt-in vs always-memoize)</td></tr><tr><td>Server environment for unit</td><td><a href="https://github.com/nuxt/test-utils/issues/531" target="_blank" rel="noreferrer">#531</a></td><td>documented (partial; optional package)</td></tr><tr><td>Server-only <code>setup()</code></td><td><a href="https://github.com/nuxt/test-utils/issues/921" target="_blank" rel="noreferrer">#921</a></td><td>out-of-scope</td></tr><tr><td><code>useRuntimeConfig</code> without Nuxt instance</td><td><a href="https://github.com/nuxt/test-utils/issues/949" target="_blank" rel="noreferrer">#949</a></td><td>out-of-scope</td></tr><tr><td><code>mockNuxtImport</code> expose mocks</td><td><a href="https://github.com/nuxt/test-utils/issues/541" target="_blank" rel="noreferrer">#541</a></td><td>out-of-scope</td></tr><tr><td>Mock already-loaded <code>#app/nuxt</code></td><td><a href="https://github.com/nuxt/test-utils/issues/693" target="_blank" rel="noreferrer">#693</a></td><td>out-of-scope</td></tr><tr><td><code>setupFiles</code> before Nuxt env</td><td><a href="https://github.com/nuxt/test-utils/issues/577" target="_blank" rel="noreferrer">#577</a></td><td>documented</td></tr><tr><td>Middleware in component tests</td><td><a href="https://github.com/nuxt/test-utils/issues/526" target="_blank" rel="noreferrer">#526</a></td><td>out-of-scope</td></tr><tr><td>msw + Nuxt env</td><td><a href="https://github.com/nuxt/test-utils/issues/1222" target="_blank" rel="noreferrer">#1222</a></td><td>documented</td></tr><tr><td>Browser mode + projects</td><td><a href="https://github.com/nuxt/test-utils/issues/1322" target="_blank" rel="noreferrer">#1322</a>, <a href="https://github.com/nuxt/test-utils/issues/984" target="_blank" rel="noreferrer">#984</a></td><td>documented (e2e ≠ browser mode)</td></tr><tr><td>Vitest 4 environment stub</td><td><a href="https://github.com/nuxt/test-utils/issues/1482" target="_blank" rel="noreferrer">#1482</a>, <a href="https://github.com/nuxt/test-utils/issues/1656" target="_blank" rel="noreferrer">#1656</a>, <a href="https://github.com/nuxt/test-utils/issues/1452" target="_blank" rel="noreferrer">#1452</a></td><td>addressed (own env package)</td></tr><tr><td>Pinia / blank router path</td><td><a href="https://github.com/nuxt/test-utils/issues/523" target="_blank" rel="noreferrer">#523</a>, <a href="https://github.com/nuxt/test-utils/issues/513" target="_blank" rel="noreferrer">#513</a></td><td>documented</td></tr></tbody></table><h2 id="vitest-platform" tabindex="-1">Vitest platform <a class="header-anchor" href="#vitest-platform" aria-label="Permalink to &quot;Vitest platform&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pain</th><th>Issue</th><th>Status</th><th>How untestutils handles it</th></tr></thead><tbody><tr><td>Monorepo first-class</td><td><a href="https://github.com/vitest-dev/vitest/issues/256" target="_blank" rel="noreferrer">#256</a></td><td>documented</td><td>Recipe map + abs paths (workspaces exist; harness stays root-safe)</td></tr><tr><td><code>cwd</code> = workspace root in subprojects</td><td><a href="https://github.com/vitest-dev/vitest/issues/5277" target="_blank" rel="noreferrer">#5277</a></td><td>addressed</td><td>Resolve recipe / fixture roots via absolute paths</td></tr><tr><td>Vite <code>root</code> ignored on workspace</td><td><a href="https://github.com/vitest-dev/vitest/issues/6855" target="_blank" rel="noreferrer">#6855</a></td><td>addressed</td><td>Same — never rely on process cwd alone</td></tr><tr><td>Timeout abort → orphan processes</td><td><a href="https://github.com/vitest-dev/vitest/issues/3077" target="_blank" rel="noreferrer">#3077</a></td><td>addressed</td><td>PID teardown + stale lock cleanup</td></tr><tr><td>Hangs / close timed out</td><td><a href="https://github.com/vitest-dev/vitest/issues/2008" target="_blank" rel="noreferrer">#2008</a></td><td>addressed</td><td>Teardown budgets + force-kill path</td></tr><tr><td>Forks runner timeout (v4)</td><td><a href="https://github.com/vitest-dev/vitest/issues/8968" target="_blank" rel="noreferrer">#8968</a></td><td>documented</td><td>Pool / isolate defaults for e2e</td></tr><tr><td><code>isolate: false</code> mock bleed</td><td><a href="https://github.com/vitest-dev/vitest/issues/11152" target="_blank" rel="noreferrer">#11152</a></td><td>documented</td><td>Prefer isolate for e2e</td></tr><tr><td>Isolate + workspace quirks</td><td><a href="https://github.com/vitest-dev/vitest/issues/6258" target="_blank" rel="noreferrer">#6258</a></td><td>documented</td><td>Dogfood matrix</td></tr><tr><td>Sharding docs / CI</td><td><a href="https://github.com/vitest-dev/vitest/issues/4269" target="_blank" rel="noreferrer">#4269</a></td><td>documented</td><td>CI shard guidance</td></tr></tbody></table><h2 id="playwright-adjacent" tabindex="-1">Playwright (adjacent) <a class="header-anchor" href="#playwright-adjacent" aria-label="Permalink to &quot;Playwright (adjacent)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pain</th><th>Issue</th><th>Status</th><th>How untestutils handles it</th></tr></thead><tbody><tr><td>Multiple web servers</td><td><a href="https://github.com/microsoft/playwright/issues/8206" target="_blank" rel="noreferrer">#8206</a></td><td>addressed</td><td>Multi-recipe / multi-target registry</td></tr><tr><td>Locks vs concurrent tests</td><td><a href="https://github.com/microsoft/playwright/issues/21484" target="_blank" rel="noreferrer">#21484</a></td><td>addressed</td><td>File locks per build identity</td></tr><tr><td>Teardown vs test timeout</td><td><a href="https://github.com/microsoft/playwright/issues/15019" target="_blank" rel="noreferrer">#15019</a></td><td>addressed</td><td>Separate teardown budgets</td></tr><tr><td>Global beforeEach hooks</td><td><a href="https://github.com/microsoft/playwright/issues/9468" target="_blank" rel="noreferrer">#9468</a></td><td>documented</td><td>Vitest + Playwright fixtures over shared recipes</td></tr></tbody></table><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="/untestutils/why">Why untestutils</a></li><li><a href="/untestutils/migration/from-nuxt-test-utils">Migrate from @nuxt/test-utils</a></li><li><a href="/untestutils/guide/demo">Demo</a></li><li>Docs site: <a href="https://s00d.github.io/untestutils/" target="_blank" rel="noreferrer">https://s00d.github.io/untestutils/</a></li><li>Repo: <a href="https://github.com/s00d/untestutils" target="_blank" rel="noreferrer">https://github.com/s00d/untestutils</a></li></ul>',14)])])}const f=e(a,[["render",o]]);export{p as __pageData,f as default};
